import sys
import json
import collections

# Use the globally injected input_data directly
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])

def find_path():
    plateau = set()
    blocked_ground = set()
    blocked_plateau = set()
    width, height = 40, 40

    if map_id == "0_220": # Safari Zone Center
        width, height = 30, 26
        # 1. Gatehouse Barrier:
        # Row 25 fence
        for x in range(0, 30):
            if x not in (14, 15):
                blocked_ground.add((x, 25))
        # Row 24 gate posts
        blocked_ground.add((13, 24))
        blocked_ground.add((15, 24))
        blocked_ground.add((16, 24))

        # 2. Row 15/16 Tree Wall:
        for x in range(0, 18):
            for y in (15, 16):
                blocked_ground.add((x, y))

        # 3. Row 9 Fence:
        for x in range(22, 28):
            blocked_ground.add((x, 9))

        # 4. Central water lake:
        for x in range(8, 22):
            for y in range(8, 14):
                blocked_ground.add((x, y))

        # 5. Rest House 1 building:
        blocked_ground.add((13, 22))
        blocked_ground.add((14, 22))

    elif map_id == "0_219": # Safari Zone West
        width, height = 30, 26
        # Bridge on Row 16:
        for x in range(5, 23):
            plateau.add((x, 16))
        # Koga's vertical stairs approach corridor:
        for x in range(5, 12):
            for y in range(17, 19):
                plateau.add((x, y))
        # Western stairs tile:
        plateau.add((6, 19))
        # Western Plateau main body:
        for x in range(4, 17):
            for y in range(6, 14):
                plateau.add((x, y))
        # Connecting bridge Row 14 & 15 (Columns 14-22):
        for x in range(14, 23):
            for y in range(14, 16):
                plateau.add((x, y))
        # Eastern Plateau Row 14-16 (Columns 20-22):
        for x in range(20, 23):
            for y in range(14, 17):
                plateau.add((x, y))

        # Ground level obstacles (z=0) based on verified blocked tiles:
        # Row 19 is blocked except for stairs at (6,19)
        for x in range(0, 30):
            if x != 6:
                blocked_ground.add((x, 19))
        for x in range(2, 10):
            for y in range(10, 14):
                blocked_ground.add((x, y))
        for x in range(10, 13):
            for y in range(9, 12):
                blocked_ground.add((x, y))
        blocked_ground.add((12, 12))
        for y in range(10, 15):
            blocked_ground.add((14, y))
        for y in range(20, 24):
            blocked_ground.add((18, y))
        for y in range(1, 14):
            blocked_ground.add((24, y))
        for y in range(14, 18):
            blocked_ground.add((23, y))
        blocked_ground.add((10, 6))
        blocked_ground.add((10, 8))

        # Plateau level obstacles (z=1):
        blocked_plateau.add((10, 6)) # solid cliff
        blocked_plateau.add((10, 8)) # solid cliff
        blocked_plateau.add((10, 7)) # solid cliff / unverified jump-down
        for y in range(9, 15):
            blocked_plateau.add((14, y)) # solid cliff Column 14 on Rows 9-14

    elif map_id == "0_217": # Safari Zone East
        width, height = 30, 26
        # Plateau tiles: Columns 11-19, Rows 4-12
        for x in range(11, 20):
            for y in range(4, 13):
                plateau.add((x, y))
        # Staircases
        plateau.add((20, 21)) # South Stairs
        plateau.add((12, 7))  # North Stairs
        plateau.add((17, 7))  # North-East Stairs

    elif map_id == "0_218": # Safari Zone North
        width, height = 40, 36
        # Eastern Plateau: Columns 25-29, Rows 25-26
        for x in range(25, 30):
            for y in range(25, 27):
                plateau.add((x, y))
        # Western Plateau:
        for x in range(15, 23):
            for y in range(20, 23):
                plateau.add((x, y))
        # Stairs:
        plateau.add((28, 27)) # Eastern Plateau stairs
        plateau.add((22, 23)) # Western Plateau stairs
        plateau.add((16, 27)) # North Plateau stairs descent

        # Static ground obstacles for Map 0_218 (Safari Zone North):
        # 1. Central water lake: Columns 8-11, Rows 8-13
        for x in range(8, 12):
            for y in range(8, 14):
                blocked_ground.add((x, y))
        # 2. Water lake Columns 4-7, Rows 14-19 (including Row 19)
        for x in range(4, 8):
            for y in range(14, 20):
                blocked_ground.add((x, y))
        # 3. Row 34 building/fence from Column 10 to Column 19 (excluding gaps at 8,9)
        # Row 34 is blocked by TYPE_2889 on many columns:
        for x in range(0, 40):
            if x not in (5, 6, 8, 9, 12, 13, 20, 21, 25, 26, 27, 28, 29, 30): # Add standard open columns
                blocked_ground.add((x, 34))
        # We explicitly block building roof at (13, 31)
        blocked_ground.add((13, 31))
        # Building roof at (18, 34) and (13, 31)
        blocked_ground.add((18, 34))
        # 4. Vertical tree walls:
        # Column 17 is completely blocked from Row 29 to Row 34
        for y in range(29, 35):
            blocked_ground.add((17, y))
        # Column 5 is completely blocked from Row 14 to Row 34
        for y in range(14, 35):
            blocked_ground.add((5, y))
        # Column 16 blocked from Row 11 to Row 19 (vertical partition)
        for y in range(11, 20):
            blocked_ground.add((16, y))

        # 5. Row 4 Tree Wall: Columns 10-19 are blocked
        for x in range(10, 20):
            blocked_ground.add((x, 4))
        # 6. Column 11 Tree partition: Rows 5-7 are blocked
        for y in range(5, 8):
            blocked_ground.add((11, y))

    start_z = 1 if (start_x, start_y) in plateau else 0
    target_z = 1 if (target_x, target_y) in plateau else 0

    queue = collections.deque([(start_x, start_y, start_z, [])])
    visited = set([(start_x, start_y, start_z)])

    while queue:
        cx, cy, cz, path = queue.popleft()
        if (cx, cy, cz) == (target_x, target_y, target_z):
            return path

        for dx, dy, btn in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
            nx, ny = cx + dx, cy + dy
            if not (0 <= nx < width and 0 <= ny < height):
                continue

            if cz == 1:
                # Must stay on plateau, unless descending stairs or jumping down:
                if (nx, ny) not in plateau:
                    # Map 0_219 descent
                    if map_id == "0_219" and (cx, cy) == (6, 19) and (nx, ny) == (6, 20):
                        ncz = 0
                    elif map_id == "0_219" and (cx, cy) == (21, 16) and (nx, ny) == (21, 17):
                        ncz = 0
                    # Map 0_218 descent
                    elif map_id == "0_218" and (cx, cy) == (16, 27) and (nx, ny) == (16, 28):
                        ncz = 0
                    elif map_id == "0_218" and (cx, cy) == (22, 23) and (nx, ny) == (22, 24):
                        ncz = 0
                    elif map_id == "0_218" and (cx, cy) == (28, 27) and (nx, ny) == (28, 28):
                        ncz = 0
                    # Map 0_217 descent
                    elif map_id == "0_217" and (cx, cy) == (20, 21) and (nx, ny) == (20, 22):
                        ncz = 0
                    elif map_id == "0_217" and (cx, cy) == (12, 7) and (nx, ny) == (12, 8):
                        ncz = 0
                    elif map_id == "0_217" and (cx, cy) == (17, 7) and (nx, ny) == (17, 8):
                        ncz = 0
                    else:
                        continue
                else:
                    ncz = 1

                if (nx, ny) in blocked_plateau:
                    continue
            else:
                # Must stay on ground and not hit obstacles or plateau boundaries
                if (nx, ny) in plateau:
                    # Unless transitioning via stairs UP:
                    if map_id == "0_219" and (cx, cy) == (21, 17) and (nx, ny) == (21, 16):
                        ncz = 1
                    elif map_id == "0_219" and (cx, cy) == (6, 20) and (nx, ny) == (6, 19):
                        ncz = 1
                    elif map_id == "0_217" and (cx, cy) == (20, 22) and (nx, ny) == (20, 21):
                        ncz = 1
                    elif map_id == "0_217" and (cx, cy) == (12, 8) and (nx, ny) == (12, 7):
                        ncz = 1
                    elif map_id == "0_217" and (cx, cy) == (17, 8) and (nx, ny) == (17, 7):
                        ncz = 1
                    elif map_id == "0_218" and (cx, cy) == (28, 28) and (nx, ny) == (28, 27):
                        ncz = 1
                    elif map_id == "0_218" and (cx, cy) == (22, 24) and (nx, ny) == (22, 23):
                        ncz = 1
                    elif map_id == "0_218" and (cx, cy) == (16, 28) and (nx, ny) == (16, 27):
                        ncz = 1
                    else:
                        continue
                else:
                    ncz = 0

                if (nx, ny) in blocked_ground:
                    continue

            state = (nx, ny, ncz)
            if state not in visited:
                visited.add(state)
                queue.append((nx, ny, ncz, path + [btn]))

    return []

print(json.dumps(find_path()))
